1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"sort"
9		"strings"
10	)
11	
12	// Reason constants for clusters that cannot enter a release plan.
13	const (
14		ReasonDisabled          = "集群已停用"
15		ReasonExcludeMatched    = "命中排除条件"
16		ReasonIncludeNotMatched = "未命中包含条件"
17	)
18	
19	// LabelCondition is a set of exact key-value matches; all must match.
20	type LabelCondition map[string]string
21	
22	// Cluster is a candidate target for a release.
23	type Cluster struct {
24		ID       string
25		Disabled bool
26		Tags     map[string]string
27	}
28	
29	// ReleasePlanInput describes an application release to plan offline.
30	type ReleasePlanInput struct {
31		App       string
32		Revision  string
33		Image     string
34		BatchSize int
35		Clusters  []Cluster
36		Include   []LabelCondition
37		Exclude   []LabelCondition
38	}
39	
40	// AppInfo identifies the application being released.
41	type AppInfo struct {
42		Name     string `json:"name"`
43		Revision string `json:"revision"`
44		Image    string `json:"image"`
45	}
46	
47	// Batch is a sequentially numbered group of cluster IDs.
48	type Batch struct {
49		Index    int      `json:"index"`
50		Clusters []string `json:"clusters"`
51	}
52	
53	// ExcludedCluster explains why a cluster is not in the plan.
54	type ExcludedCluster struct {
55		ID     string `json:"id"`
56		Reason string `json:"reason"`
57	}
58	
59	// ReleasePlan is the deterministic offline release plan.
60	type ReleasePlan struct {
61		App      AppInfo           `json:"app"`
62		Batches  []Batch           `json:"batches"`
63		Excluded []ExcludedCluster `json:"excluded"`
64	}
65	
66	// ParseReleaseInput reads a release plan document and validates its fields.
67	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
68		dec := json.NewDecoder(bytes.NewReader(data))
69		dec.UseNumber()
70		var doc map[string]any
71		if err := dec.Decode(&doc); err != nil {
72			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
73		}
74		if dec.More() {
75			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
76		}
77		return buildReleaseInput(doc)
78	}
79	
80	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
81		app, err := requiredString(doc, "app")
82		if err != nil {
83			return ReleasePlanInput{}, err
84		}
85		revision, err := requiredString(doc, "revision")
86		if err != nil {
87			return ReleasePlanInput{}, err
88		}
89		image, err := requiredString(doc, "image")
90		if err != nil {
91			return ReleasePlanInput{}, err
92		}
93		batchSize, err := positiveInt(doc, "batchSize")
94		if err != nil {
95			return ReleasePlanInput{}, err
96		}
97		clusters, err := parseClusters(doc["clusters"])
98		if err != nil {
99			return ReleasePlanInput{}, err
100		}
101		include, err := parseConditions(doc["include"], "include")
102		if err != nil {
103			return ReleasePlanInput{}, err
104		}
105		exclude, err := parseConditions(doc["exclude"], "exclude")
106		if err != nil {
107			return ReleasePlanInput{}, err
108		}
109	
110		return ReleasePlanInput{
111			App:       app,
112			Revision:  revision,
113			Image:     image,
114			BatchSize: batchSize,
115			Clusters:  clusters,
116			Include:   include,
117			Exclude:   exclude,
118		}, nil
119	}
120	
121	// ValidateReleaseInput checks that a release configuration is well-formed:
122	// app/revision/image are non-empty, batchSize is a positive integer, cluster
123	// IDs are unique across every candidate (including disabled and filtered-out
124	// clusters), and tag/condition keys are non-empty. Errors name the field and
125	// the position in its list; within a cluster the ID is checked before its
126	// tags, and tag keys are examined in ascending order so repeated calls report
127	// the same error. The input is never mutated. MakeReleasePlan calls this
128	// automatically; library callers may use it to validate without planning.
129	func ValidateReleaseInput(in ReleasePlanInput) error {
130		if strings.TrimSpace(in.App) == "" {
131			return errors.New(`字段 "app" 不能为空或只含空白`)
132		}
133		if strings.TrimSpace(in.Revision) == "" {
134			return errors.New(`字段 "revision" 不能为空或只含空白`)
135		}
136		if strings.TrimSpace(in.Image) == "" {
137			return errors.New(`字段 "image" 不能为空或只含空白`)
138		}
139		if in.BatchSize <= 0 {
140			return errors.New(`字段 "batchSize" 必须是正整数`)
141		}
142		seen := make(map[string]struct{}, len(in.Clusters))
143		for i, c := range in.Clusters {
144			if strings.TrimSpace(c.ID) == "" {
145				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
146			}
147			if _, dup := seen[c.ID]; dup {
148				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
149			}
150			seen[c.ID] = struct{}{}
151			if err := validateTagKeys(i, c.Tags); err != nil {
152				return err
153			}
154		}
155		if err := validateConditionKeys("include", in.Include); err != nil {
156			return err
157		}
158		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
159			return err
160		}
161		return nil
162	}
163	
164	// validateTagKeys checks tag keys in ascending order for deterministic errors.
165	func validateTagKeys(clusterIndex int, tags map[string]string) error {
166		keys := make([]string, 0, len(tags))
167		for k := range tags {
168			keys = append(keys, k)
169		}
170		sort.Strings(keys)
171		for _, k := range keys {
172			if k == "" {
173				return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
174			}
175		}
176		return nil
177	}
178	
179	// validateConditionKeys checks that every condition is non-empty and has only
180	// non-empty keys; conditions are visited in original order and keys in
181	// ascending order for deterministic errors.
182	func validateConditionKeys(field string, conds []LabelCondition) error {
183		for i, cond := range conds {
184			if len(cond) == 0 {
185				return fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
186			}
187			keys := make([]string, 0, len(cond))
188			for k := range cond {
189				keys = append(keys, k)
190			}
191			sort.Strings(keys)
192			for _, k := range keys {
193				if k == "" {
194					return fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
195				}
196			}
197		}
198		return nil
199	}
200	
201	func requiredString(doc map[string]any, field string) (string, error) {
202		v, ok := doc[field]
203		if !ok {
204			return "", fmt.Errorf("缺少必需字段 %q", field)
205		}
206		s, ok := v.(string)
207		if !ok {
208			return "", fmt.Errorf("字段 %q 必须是字符串", field)
209		}
210		if strings.TrimSpace(s) == "" {
211			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
212		}
213		return s, nil
214	}
215	
216	func positiveInt(doc map[string]any, field string) (int, error) {
217		v, ok := doc[field]
218		if !ok {
219			return 0, fmt.Errorf("缺少必需字段 %q", field)
220		}
221		n, ok := v.(json.Number)
222		if !ok {
223			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
224		}
225		i, err := n.Int64()
226		if err != nil || i <= 0 {
227			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
228		}
229		return int(i), nil
230	}
231	
232	func parseClusters(v any) ([]Cluster, error) {
233		if v == nil {
234			return nil, errors.New("缺少必需字段 \"clusters\"")
235		}
236		raw, ok := v.([]any)
237		if !ok {
238			return nil, errors.New("字段 \"clusters\" 必须是数组")
239		}
240		clusters := make([]Cluster, 0, len(raw))
241		seen := make(map[string]bool)
242		for i, item := range raw {
243			obj, ok := item.(map[string]any)
244			if !ok {
245				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
246			}
247			id, err := requiredString(obj, "id")
248			if err != nil {
249				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
250			}
251			if seen[id] {
252				return nil, fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, id)
253			}
254			seen[id] = true
255	
256			disabled := false
257			if dv, present := obj["disabled"]; present {
258				b, ok := dv.(bool)
259				if !ok {
260					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
261				}
262				disabled = b
263			}
264	
265			tags := map[string]string{}
266			if tv, present := obj["tags"]; present {
267				tm, ok := tv.(map[string]any)
268				if !ok {
269					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
270				}
271				keys := make([]string, 0, len(tm))
272				for k := range tm {
273					keys = append(keys, k)
274				}
275				sort.Strings(keys)
276				for _, k := range keys {
277					if k == "" {
278						return nil, fmt.Errorf("集群 %q 的标签键不能为空", id)
279					}
280					sv, ok := tm[k].(string)
281					if !ok {
282						return nil, fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k)
283					}
284					tags[k] = sv
285				}
286			}
287	
288			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
289		}
290		return clusters, nil
291	}
292	
293	func parseConditions(v any, field string) ([]LabelCondition, error) {
294		if v == nil {
295			return []LabelCondition{}, nil
296		}
297		raw, ok := v.([]any)
298		if !ok {
299			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
300		}
301		conds := make([]LabelCondition, 0, len(raw))
302		for i, item := range raw {
303			obj, ok := item.(map[string]any)
304			if !ok {
305				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
306			}
307			if len(obj) == 0 {
308				return nil, fmt.Errorf("%s[%d] 不能为空条件对象", field, i)
309			}
310			cond := LabelCondition{}
311			keys := make([]string, 0, len(obj))
312			for k := range obj {
313				keys = append(keys, k)
314			}
315			sort.Strings(keys)
316			for _, k := range keys {
317				if k == "" {
318					return nil, fmt.Errorf("%s[%d] 的标签键不能为空", field, i)
319				}
320				sv, ok := obj[k].(string)
321				if !ok {
322					return nil, fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k)
323				}
324				cond[k] = sv
325			}
326			conds = append(conds, cond)
327		}
328		return conds, nil
329	}
330	
331	// MakeReleasePlan selects available clusters, orders them by ID, and splits
332	// them into batches. It validates the input first and never mutates it.
333	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
334		if err := ValidateReleaseInput(in); err != nil {
335			return ReleasePlan{}, err
336		}
337		if len(in.Clusters) == 0 {
338			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
339		}
340	
341		selected := []string{}
342		excluded := []ExcludedCluster{}
343		for _, c := range in.Clusters {
344			switch {
345			case c.Disabled:
346				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
347			case matchesAny(c.Tags, in.Exclude):
348				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
349			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
350				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
351			default:
352				selected = append(selected, c.ID)
353			}
354		}
355	
356		sort.Strings(selected)
357		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
358	
359		if len(selected) == 0 {
360			var b strings.Builder
361			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
362			for _, e := range excluded {
363				b.WriteString("\n  ")
364				b.WriteString(e.ID)
365				b.WriteString("：")
366				b.WriteString(e.Reason)
367			}
368			return ReleasePlan{}, errors.New(b.String())
369		}
370	
371		batches := []Batch{}
372		for i := 0; i < len(selected); i += in.BatchSize {
373			end := i + in.BatchSize
374			if end > len(selected) {
375				end = len(selected)
376			}
377			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
378		}
379	
380		return ReleasePlan{
381			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
382			Batches:  batches,
383			Excluded: excluded,
384		}, nil
385	}
386	
387	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
388		for _, cond := range conditions {
389			if matchesAll(tags, cond) {
390				return true
391			}
392		}
393		return false
394	}
395	
396	func matchesAll(tags map[string]string, cond LabelCondition) bool {
397		for k, v := range cond {
398			tv, ok := tags[k]
399			if !ok || tv != v {
400				return false
401			}
402		}
403		return true
404	}
405

