func walkObject(dec *json.Decoder, path string) error {
    seen := map[string]struct{}{}
    for {
        tok, err := dec.Token()
        if err != nil { return err }
        if d, ok := tok.(json.Delim); ok {
            if d == '}' { return nil }
            return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
        }
        key, ok := tok.(string)
        if !ok { return fmt.Errorf("JSON 格式错误: 期望对象成员名") }
        if _, dup := seen[key]; dup {
            return fmt.Errorf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", key, path)
        }
        seen[key] = struct{}{}
        if err := walkValue(dec, path+"."+key); err != nil {
            return err
        }
    }
}

func walkArray(dec *json.Decoder, path string) error {
    for i := 0; ; i++ {
        // peek: read first token of element
        tok, err := dec.Token()
        if err != nil { return err }
        if d, ok := tok.(json.Delim); ok {
            if d == ']' { return nil }
            if d != '{' && d != '[' {
